    var frac = state.total ? (state.remaining / state.total) : 0;
    el.prog.style.strokeDashoffset = CIRC * (1 - frac);
    el.phase.textContent = state.mode === 'work' ? 'Work session' : 'Break time';
    el.start.textContent = state.running ? 'Pause' : 'Start';
