    el.tabBreak.classList.toggle('active', state.mode === 'break');
    el.tabWork.setAttribute('aria-selected', state.mode === 'work');
    el.tabBreak.setAttribute('aria-selected', state.mode === 'break');
    document.title = fmt(state.remaining) + ' · ' + (state.mode === 'work' ? 'Work' : 'Break');
